                <select name="status" class="rounded-xl border border-white/10 bg-black px-4 py-3 text-sm"><option value="">Semua status</option><?php foreach(['NEW','AUTO_REPLIED','UNREAD','IN_PROGRESS','FOLLOW_UP','DONE'] as $s): ?><option><?= $s ?></option><?php endforeach ?></select>
                <select name="pic" class="rounded-xl border border-white/10 bg-black px-4 py-3 text-sm"><option value="">Semua PIC</option><?php foreach($pics as $pic): ?><option value="<?= $pic['id'] ?>"><?= esc($pic['name']) ?></option><?php endforeach ?></select>
                <input type="date" name="date" class="rounded-xl border border-white/10 bg-black px-4 py-3 text-sm">
