  {"action":"SEND_MESSAGE","message":"Halo, ada yang bisa kami bantu?"},
  {"action":"CHANGE_STATUS","status":"FOLLOW_UP"}
]</textarea><button class="w-full rounded-xl bg-accent px-4 py-3 font-bold text-black">Simpan Workflow</button></form>
